import { Order } from './types';
export interface OrderPosition { createdAt: string; id: string }
function compareKey(a: OrderPosition, b: OrderPosition): number {
  return a.createdAt < b.createdAt ? -1 : a.createdAt > b.createdAt ? 1 : a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
}
export class OrderRepository {
  constructor(private readonly rows: Order[]) {}
  /**
   * Returns the tenant's orders sorted ascending by (createdAt, id).
   * When `after` is given, only orders strictly after that pair are returned
   * (the pair need not exist). Filtering by tenant happens before positioning.
   * The input array and its rows are never mutated.
   */
  list(tenant: string, after?: OrderPosition): Order[] {
    return this.rows
      .filter(row => row.tenant === tenant && (after === undefined || compareKey(row, after) > 0))
      .sort(compareKey);
  }
}
